import os
import re

def get_total_sum():
    total_sum = 0
    for root, dirs, files in os.walk('reports/q2'):
        for file in files:
            if file.endswith('.txt'):  # assuming report files are .txt
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    lines = f.readlines()
                    for line in lines:
                        if line.startswith('TOTAL:'):
                            # Extract the number after 'TOTAL:'
                            match = re.search(r'TOTAL:\s*(\d+)', line)
                            if match:
                                total_sum += int(match.group(1))
    return total_sum

print(get_total_sum())

